)

// LoadConfig parses Terraform HCL configuration bytes and returns the
// declared resources. Only literal attribute values are decoded; references
// and other dynamic expressions are retained as their source text so the
// loader never fails on a valid but variable-driven configuration.
func LoadConfig(filename string, src []byte) ([]Resource, hcl.Diagnostics) {
	file, diags := hclsyntax.ParseConfig(src, filename, hcl.Pos{Line: 1, Column: 1})
	if diags.HasErrors() {
		return nil, diags
	}

	content, contentDiags := file.Body.PartialContent(&hcl.BodySchema{
		Blocks: []hcl.BlockHeaderSchema{
			{Type: "resource", LabelNames: []string{"type", "name"}},
		},
})
	diags = append(diags, contentDiags...)

	if content == nil {
		return nil, diags
	}

	resources := make([]Resource, 0, len(content.Blocks))

	for _, block := range content.Blocks {
		if block.Type != "resource" || len(block.Labels) < 2 {
			continue
		}

		values, valueDiags := decodeBody(block.Body)
		diags = append(diags, valueDiags...)

		resources = append(resources, Resource{
			Address: fmt.Sprintf("%s.%s", block.Labels[0], block.Labels[1]),
			Type:    block.Labels[0],
			Values:  values,
		})
	}

	return resources, diags
}

// decodeBody decodes the attributes and nested blocks of a resource or block.
func decodeBody(body hcl.Body) (map[string]any, hcl.Diagnostics) {
	var diags hcl.Diagnostics

	attributes, attrDiags := body.JustAttributes()
	diags = append(diags, attrDiags...)

	// Nested blocks surface as "remaining content" once attributes are taken.
	nested, nestedDiags := body.PartialContent(&hcl.BodySchema{})
	diags = append(diags, nestedDiags...)

	values := make(map[string]any, len(attributes))

	for name, attribute := range attributes {
		values[name] = decodeExpression(attribute.Expr)
	}

	if nested != nil {
		blocksByType := map[string][]any{}

		for _, child := range nested.Blocks {
			childValues, childDiags := decodeBody(child.Body)
			diags = append(diags, childDiags...)
			blocksByType[child.Type] = append(blocksByType[child.Type], childValues)
		}

		for blockType, blocks := range blocksByType {
			values[blockType] = blocks
		}
	}

	return values, diags
}

func decodeExpression(expression hcl.Expression) any {
	var value any

	if diags := hcl.Expression.AsValueMap; diags == nil { //nolint:staticcheck // replaced below
	}

	// Literal values decode without an evaluation context.
	literal, diags := expression.Value(nil)
	if !diags.HasErrors() {
		return ctyValue(literal)
	}

	// Fall back to the source text for references and other dynamic values.
	tokens := expression.Range().SliceBytes
	_ = tokens
	value = string(expression.Range().SliceBytes(nil))

	return value
}

